import { test, expect } from '@playwright/test';

test.describe('Cookie Consent Banner - Acceptance', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/settings');
  });

  test('should hide cookie consent banner after user accepts cookies', async ({ page }) => {
    // Verify consent banner is visible
    const consentBanner = page.getByRole('alert');
    await expect(consentBanner).toBeVisible();

    // Verify consent button is visible and enabled
    const acceptButton = page.getByRole('button', { name: /accept/i });
    await expect(acceptButton).toBeVisible();

    // Verify consent text is visible
    const consentText = page.getByText(/we use cookies to improve your experience/i);
    await expect(consentText).toBeVisible();

    // Verify consent banner has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Click accept button
    await acceptButton.click();

    // Verify consent banner is no longer visible
    await expect(consentBanner).not.toBeVisible();

    // Verify consent text is no longer visible
    await expect(consentText).not.toBeVisible();

    // Verify consent banner close button is still visible
    await expect(closeButton).toBeVisible();

    // Verify consent banner is not visible after closing
    await expect(consentBanner).not.toBeVisible();

    // Verify consent banner is not visible after navigating away
    await page.goto('/dashboard');
    await expect(consentBanner).not.toBeVisible();
  });

  test('should not hide cookie consent banner if user rejects cookies', async ({ page }) => {
    // Verify consent banner is visible
    const consentBanner = page.getByRole('alert');
    await expect(consentBanner).toBeVisible();

    // Verify consent button is visible and enabled
    const acceptButton = page.getByRole('button', { name: /accept/i });
    await expect(acceptButton).toBeVisible();

    // Verify consent text is visible
    const consentText = page.getByText(/we use cookies to improve your experience/i);
    await expect(consentText).toBeVisible();

    // Verify consent banner has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Click reject button
    const rejectButton = page.getByRole('button', { name: /reject/i });
    await rejectButton.click();

    // Verify consent banner remains visible
    await expect(consentBanner).toBeVisible();

    // Verify consent text is still visible
    await expect(consentText).toBeVisible();

    // Verify consent banner close button is still visible
    await expect(closeButton).toBeVisible();

    // Verify consent banner is still visible after navigating away
    await page.goto('/dashboard');
    await expect(consentBanner).toBeVisible();
  });
});
